import itertools

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            if (dr, dc) in vectors:
                return False
            vectors.add((dr, dc))
    return True

# Search all permutations of 0..5
for perm in itertools.permutations(range(6)):
    if is_costas(perm):
        print("Found:", list(perm))
        break
else:
    print("No solution found")

def verify_costas(perm):
    n = len(perm)
    vectors = {}
    ok = True
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            if (dr, dc) in vectors:
                print(f"Conflict: ({dr},{dc}) from columns {i},{j} and {vectors[(dr,dc)]}")
                ok = False
            vectors[(dr, dc)] = (i, j)
    if ok:
        print("All vectors are distinct!")
        print("Vectors:", sorted(vectors.keys()))
    return ok

perm = [0, 1, 4, 3, 5, 2]
verify_costas(perm)

# Also print the grid
print("\nGrid representation:")
for r in range(5, -1, -1):
    line = ""
    for c in range(6):
        if perm[c] == r:
            line += "X "
        else:
            line += ". "
    print(line)
print("  0 1 2 3 4 5 (columns)")
print("Rows: 0=bottom, 5=top")

# Count all Costas arrays of order 6
import itertools

def is_costas(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dr = perm[j] - perm[i]
            dc = j - i
            if (dr, dc) in vectors:
                return False
            vectors.add((dr, dc))
    return True

solutions = []
for perm in itertools.permutations(range(6)):
    if is_costas(perm):
        solutions.append(list(perm))

print(f"Total solutions: {len(solutions)}")
for s in solutions:
    print(s)
